-- Reemplaza plantillas mexicana / bar / cafeteria / italiana
-- Referencias: Edit.org (mexicana) + Adobe Express (bar, café, italiana)

-- Liberar FKs de menús que usaban plantillas de estas categorías
UPDATE menus SET template_id = NULL
WHERE template_id IN (
  'tpl-mexicana-1', 'tpl-bar-1', 'tpl-bar-2', 'tpl-cafe-1', 'tpl-cafe-2', 'tpl-italiana-1', 'tpl-italiana-2'
)
OR template_id LIKE 'tpl-mex-%'
OR template_id LIKE 'tpl-bar-%'
OR template_id LIKE 'tpl-cafe-%'
OR template_id LIKE 'tpl-ita-%';

DELETE FROM templates WHERE id IN (
  'tpl-mexicana-1', 'tpl-bar-1', 'tpl-bar-2', 'tpl-cafe-1', 'tpl-cafe-2', 'tpl-italiana-1', 'tpl-italiana-2'
)
OR id LIKE 'tpl-mex-%'
OR id LIKE 'tpl-bar-%'
OR id LIKE 'tpl-cafe-%'
OR id LIKE 'tpl-ita-%';
















